"use strict";function query(n){$.ajax({url:_global.root+"applicants/index",dataType:"html",method:"POST",data:{FullName:$("#FullName").val(),PositionId:$("#PositionId").val(),Status:$("#Status").val(),FromDate:$("#FromDate").val(),ToDate:$("#ToDate").val(),PageNumber:$("#PageNumber").val(),PageSize:$("#PageSize").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#applicants-detail").html(n);floatThead("table#data");showRowInfo();disableBtnPreNext()},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteApplicant(n,t){confirm("Are you sure you want to delete this applicant?",function(){$.post(_global.root+"applicants/Delete",{id:n,fileName:t},function(t){t.IsSuccessful?($("#row"+n).remove(),autoIndex()):alert(t.Message)})})}function eventExportExcel(){$("#exportExcel").on("click",function(n){n.preventDefault();window.location.href=_global.root+"Export/ApplicantsReport?fullName="+$("#FullName").val()+"&positionId="+$("#PositionId").val()+"&status="+$("#Status").val()+"&fromDate="+$("#FromDate").val()+"&toDate="+$("#ToDate").val()+"&pageNumber="+$("#PageNumber").val()+"&pageSize="+$("#PageSize").val()})}function pageSizeChanged(){const n=document.getElementById("total-row"),t=n!=null?parseInt(n.value,10):0,i=document.getElementById("PageNumber").value,r=document.getElementById("PageSize").value;(i-1)*r+1>t&&(document.getElementById("PageNumber").value=1);query(!1)}function showRowInfo(){const n=parseInt($("#total-row").val(),10),t=$(".pagination"),i=$("#item-range-start"),r=$("#item-range-end"),u=$("#total-items");if(n!==0){const f=parseInt($("#PageNumber").val(),10),e=parseInt($("#PageSize").val(),10),o=(f-1)*e+1,s=Math.min(f*e,n);i.text(o);r.text(s);u.text(n);t.show()}else t.hide()}function disableBtnPreNext(){const t=parseInt($("#total-row").val(),10),i=parseInt($("#PageSize").val(),10),r=Math.ceil(t/i),n=parseInt($("#PageNumber").val(),10);$(".mdi-chevron-left, .mdi-chevron-double-left").toggleClass("disabled",n===1);$(".mdi-chevron-right, .mdi-chevron-double-right").toggleClass("disabled",n===r)}function clickBtnPrevNext(){function n(n){const t=i();switch(n){case"btnNext":return t+1;case"btnPrev":return t-1;case"btnDoubleNext":return u();case"btnDoublePrev":return 1;default:return t}}function t(n){r(n);query(!1)}function i(){return parseInt(document.getElementById("PageNumber").value)}function r(n){document.getElementById("PageNumber").value=n}function u(){const n=document.getElementById("total-row"),t=n!=null?parseInt(n.value,10):0,i=parseInt(document.getElementById("PageSize").value,10);return Math.ceil(t/i)}["btnNext","btnPrev","btnDoubleNext","btnDoublePrev"].forEach(i=>{const r=document.getElementById(i);r.addEventListener("click",function(){this.classList.contains("disabled")||t(n(i))})})}function enterPageNumber(){$("#PageNumber").keyup(n=>{const i=parseInt($("#total-row").val(),10),r=parseInt($("#PageSize").val(),10),u=Math.ceil(i/r),t=parseInt($(n.currentTarget).val(),10);n.keyCode===13&&t>0&&t<=u&&query(!1)})}$(document).ready(function(){$("#FullName").keyup(function(n){n.keyCode===13&&query(!1)});$("#submit").on("click",function(){query(!1)});query(!0);eventExportExcel();clickBtnPrevNext();enterPageNumber()});